import { VerifyOptions, ReferenceArg, BothResult, NormalizedVerificationSuccess, NormalizedDashenVerification, NormalizedDashenDataVerification, NormalizedVerificationFailed } from "../types";
import { firstKey, toNumber } from "../utils";
import { HttpClient } from "./base";

export async function verifyDashenAdapter(
    http: HttpClient,
    args: ReferenceArg,
    opts: VerifyOptions = {},
): Promise<BothResult<NormalizedDashenVerification> | NormalizedDashenVerification> {
    const raw = await http.request("/verify-dashen", {
        method: "GET",
        query: { reference: args.reference },
    });

    const payload: any = (raw && typeof raw === "object" && (raw as any).data) ? (raw as any).data : raw;

    if (opts.mode === "raw") return raw;

    const amount = toNumber(firstKey(payload, ["amount", "txnAmount", "total"]));
    const currency = firstKey(payload, ["currency"]) ?? (amount != null ? "ETB" : null);
    const payerName = firstKey(payload, ["payerName", "senderName", "sender"]);
    const payerPhone = firstKey(payload, ["payerPhone", "phone"]);
    const receiverName = firstKey(payload, ["receiverName", "merchantName", "receiver"]);
    const receiverAccount = firstKey(payload, ["receiverAccount", "account"]);
    const txnDate = firstKey(payload, ["txnDate", "date", "timestamp"]);
    const statusText = firstKey(payload, ["statusText", "status", "message"]);

    const ok = (/success|completed|complete/i.test(String(statusText ?? ""))
        || String(firstKey(payload, ["ok", "valid"])).toLowerCase() === "true")
        && amount != null
        && currency != null
        && payerName != null
        && payerPhone != null
        && receiverName != null
        && receiverAccount != null
        && txnDate != null;

    if (!ok) {
        var errorMessage: NormalizedVerificationFailed = {
            ok: false,
            provider: "dashen",
            error: statusText ? String(statusText).toLowerCase() : "mismatch",
        };

        if (opts.mode == "both") {
            return {
                normalized: errorMessage,
                raw,
            };
        } else {
            return errorMessage;
        }
    }

    const normalized: NormalizedVerificationSuccess<NormalizedDashenDataVerification> = {
        ok: true,
        provider: "dashen",
        data: {
            reference: args.reference,
            amount: amount ?? 0,
            currency,
            payerName: payerName,
            payerPhone: payerPhone,
            receiverName: receiverName,
            receiverAccount: receiverAccount,
            txnDate: txnDate,
            statusText: statusText,
            status: "verified"
        },
        raw,
    };

    if (opts.mode === "both") return { normalized, raw };
    return normalized;
}
