import {
  BothResult,
  NormalizedUniversalVerification,
  VerifyOptions,
  UniversalArgs,
  NormalizedTelebirrDataVerification,
  NormalizedCBEDataVerification,
  NormalizedAbyssiniaDataVerification,
  NormalizedDashenDataVerification,
  NormalizedCBEBirrDataVerification,
  NormalizedVerificationSuccess,
  NormalizedVerificationFailed,
  Provider,
} from "../types";
import { firstKey, toNumber } from "../utils";
import { HttpClient } from "./base";

export async function verifyUniversalAdapter(
  http: HttpClient,
  args: UniversalArgs,
  opts: VerifyOptions = {},
): Promise<BothResult<NormalizedUniversalVerification> | NormalizedUniversalVerification> {
  const body: Record<string, any> = { reference: args.reference };
  if (args.suffix) body.suffix = args.suffix;
  if (args.phoneNumber) body.phoneNumber = args.phoneNumber;

  const raw = await http.request("/verify", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });

  if (opts.mode === "raw") return raw as any;

  const payload: any =
    raw && typeof raw === "object" && (raw as any).data ? (raw as any).data : raw;

  // We will attempt to figure out what provider this response belongs to based on the payload fields.
  // Let's extract the common fields
  const amount = toNumber(firstKey(payload, ["amount", "txnAmount", "total", "settledAmount"]));
  const currency = firstKey(payload, ["currency", "curr"]) ?? (amount != null ? "ETB" : null);
  const successRaw = firstKey(payload, ["success", "ok", "valid"]);
  const isSuccess = String(successRaw).toLowerCase() === "true" || successRaw === true;

  // Check if it's already a failed response from the API
  const APIError = (raw as any).error;

  // Detect provider
  let detectedProvider: Provider | null = null;

  // Let's see if the API explicitly gives us a provider field on the base object
  const explicitProvider = firstKey(raw, ["provider", "bank", "type"]);
  if (explicitProvider) {
    if (/telebirr/i.test(String(explicitProvider))) detectedProvider = "telebirr";
    else if (/abyssinia/i.test(String(explicitProvider))) detectedProvider = "abyssinia";
    else if (/cbebirr/i.test(String(explicitProvider))) detectedProvider = "cbebirr";
    else if (/dashen/i.test(String(explicitProvider))) detectedProvider = "dashen";
    else if (/cbe/i.test(String(explicitProvider))) detectedProvider = "cbe";
  }

  if (!detectedProvider) {
    // Heuristic detection based on fields
    if (firstKey(payload, ["payerTelebirrNo", "serviceFeeVAT"]) != null)
      detectedProvider = "telebirr";
    else if (firstKey(payload, ["reason"]) != null && firstKey(payload, ["payerAccount"]) != null) {
      // CBE or Abyssinia
      if (firstKey(payload, ["receiverAccount"]) != null) detectedProvider = "cbe";
      else detectedProvider = "abyssinia";
    } else if (firstKey(payload, ["payerPhone"]) != null) {
      // Dashen or CBE Birr. Without explicit tagging, they look similar. Default to cbebirr or infer from reference format.
      if (/^FT/i.test(args.reference) || args.reference.length > 10) detectedProvider = "cbebirr";
      else detectedProvider = "dashen";
    } else {
      // Fallback, default to CBE if we really can't tell, or just throw error down the line
      detectedProvider = "cbe";
    }
  }

  if (!isSuccess && APIError) {
    const err: NormalizedVerificationFailed = {
      ok: false,
      provider: detectedProvider || ("unknown" as any),
      error: String(APIError),
    };
    if (opts.mode === "both") return { normalized: err as any, raw };
    return err as any;
  }

  let normalizedData: any = null;
  let fallbackError = "mismatch";

  if (detectedProvider === "telebirr") {
    const totalAmount = toNumber(firstKey(payload, ["totalPaidAmount"]));
    const payerName = firstKey(payload, ["payerName"]);
    const payerPhone = firstKey(payload, ["payerTelebirrNo"]);
    const receiverName = firstKey(payload, ["creditedPartyName"]);
    const receiverAccount = firstKey(payload, ["creditedPartyAccountNo"]);
    const txnDate = firstKey(payload, ["paymentDate"]);
    const statusText = firstKey(payload, ["transactionStatus"]);
    const serviceFee = toNumber(firstKey(payload, ["serviceFee"]));
    const serviceFeeVAT = toNumber(firstKey(payload, ["serviceFeeVAT"]));
    const bankName = firstKey(payload, ["bankName"]);

    const statusOk = /success|completed|complete/i.test(String(statusText ?? "")) || isSuccess;

    if (
      statusOk &&
      amount != null &&
      totalAmount != null &&
      currency != null &&
      payerName != null &&
      payerPhone != null &&
      receiverName != null &&
      receiverAccount != null &&
      txnDate != null &&
      serviceFee != null &&
      serviceFeeVAT != null &&
      bankName != null
    ) {
      const data: NormalizedTelebirrDataVerification = {
        reference: args.reference,
        amount: amount ?? 0,
        currency,
        payerName,
        payerPhone,
        receiverName,
        receiverAccount,
        bankName,
        txnDate,
        serviceFee: serviceFee ?? 0,
        serviceFeeVAT: serviceFeeVAT ?? 0,
        totalAmount: totalAmount ?? 0,
        statusText,
        status: "verified",
      };
      normalizedData = data;
    } else {
      fallbackError = statusText ? String(statusText).toLowerCase() : "mismatch";
    }
  } else if (detectedProvider === "cbe") {
    const payerName = firstKey(payload, ["payer"]);
    const payerAccount = firstKey(payload, ["payerAccount"]);
    const receiverName = firstKey(payload, ["receiver"]);
    const receiverAccount = firstKey(payload, ["receiverAccount"]);
    const txnDate = firstKey(payload, ["date"]);
    const reference = firstKey(payload, ["reference"]) ?? args.reference;
    const reason = firstKey(payload, ["reason"]);

    if (
      isSuccess &&
      amount != null &&
      currency != null &&
      payerName != null &&
      payerAccount != null &&
      receiverName != null &&
      receiverAccount != null &&
      txnDate != null &&
      reason != null
    ) {
      const data: NormalizedCBEDataVerification = {
        reference,
        amount: amount ?? 0,
        currency,
        payerName,
        payerAccount,
        receiverName,
        receiverAccount,
        txnDate,
        reason,
      };
      normalizedData = data;
    }
  } else if (detectedProvider === "abyssinia") {
    const payerName = firstKey(payload, ["payer"]);
    const payerAccount = firstKey(payload, ["payerAccount"]);
    const receiverName = firstKey(payload, ["receiver"]);
    const txnDate = firstKey(payload, ["date"]);
    const reason = firstKey(payload, ["reason"]);

    if (
      isSuccess &&
      amount != null &&
      currency != null &&
      payerName != null &&
      payerAccount != null &&
      receiverName != null &&
      reason != null &&
      txnDate != null
    ) {
      const data: NormalizedAbyssiniaDataVerification = {
        reference: args.reference,
        amount: amount ?? 0,
        currency,
        payerName,
        payerAccount,
        receiverName,
        txnDate,
        reason,
      };
      normalizedData = data;
    }
  } else if (detectedProvider === "dashen" || detectedProvider === "cbebirr") {
    const payerName = firstKey(payload, ["payerName", "senderName", "sender"]);
    const payerPhone = firstKey(payload, ["payerPhone", "phone"]);
    const receiverName = firstKey(payload, ["receiverName", "merchantName", "receiver"]);
    const receiverAccount = firstKey(payload, ["receiverAccount", "account"]);
    const txnDate = firstKey(payload, ["txnDate", "date", "timestamp"]);
    const statusText = firstKey(payload, ["statusText", "status", "message"]);

    const statusOk = /success|completed|complete/i.test(String(statusText ?? "")) || isSuccess;

    if (
      statusOk &&
      amount != null &&
      currency != null &&
      payerName != null &&
      payerPhone != null &&
      receiverName != null &&
      receiverAccount != null &&
      txnDate != null
    ) {
      const data: NormalizedDashenDataVerification | NormalizedCBEBirrDataVerification = {
        reference: args.reference,
        amount: amount ?? 0,
        currency,
        payerName,
        payerPhone,
        receiverName,
        receiverAccount,
        txnDate,
        statusText,
        status: "verified",
      };
      normalizedData = data;
    } else {
      fallbackError = statusText ? String(statusText).toLowerCase() : "mismatch";
    }
  }

  if (!normalizedData) {
    var errorMessage: NormalizedVerificationFailed = {
      ok: false,
      provider: (detectedProvider as any) || "unknown",
      error: APIError ?? fallbackError,
    };

    if (opts.mode == "both") return { normalized: errorMessage as any, raw };
    return errorMessage as any;
  }

  const successNormalized: NormalizedVerificationSuccess<any> = {
    ok: true,
    provider: detectedProvider,
    data: normalizedData,
    raw,
  };

  if (opts.mode === "both") return { normalized: successNormalized as any, raw };
  return successNormalized as any;
}
