import { BothResult, NormalizedTelebirrDataVerification, NormalizedTelebirrVerification, NormalizedVerificationFailed, NormalizedVerificationSuccess, VerifyOptions } from "../types";
import { firstKey, toNumber } from "../utils";
import { HttpClient } from "./base";

export type TelebirrArgs = { reference: string };

export async function verifyTelebirrAdapter(
    http: HttpClient,
    args: TelebirrArgs,
    opts: VerifyOptions = {},
): Promise<BothResult<NormalizedTelebirrVerification> | NormalizedTelebirrVerification> {
    const raw = await http.request("/verify-telebirr", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ reference: args.reference }),
    });

    const payload: any = (raw && typeof raw === "object" && (raw as any).data) ? (raw as any).data : raw;

    if (opts.mode === "raw") return raw;

    // best-effort normalization from typical fields
    const amount = toNumber(firstKey(payload, ["settledAmount"]));
    const totalAmount = toNumber(firstKey(payload, ["totalPaidAmount"]));
    const currency = firstKey(payload, ["currency", "curr"]) ?? (amount != null ? "ETB" : null);
    const payerName = firstKey(payload, ["payerName"]);
    const payerPhone = firstKey(payload, ["payerTelebirrNo"]);
    const receiverName = firstKey(payload, ["creditedPartyName"]);
    const receiverAccount = firstKey(payload, ["creditedPartyAccountNo"]);
    const txnDate = firstKey(payload, ["paymentDate"]);
    const statusText = firstKey(payload, ["transactionStatus"]);
    const serviceFee = toNumber(firstKey(payload, ["serviceFee"]));
    const serviceFeeVAT = toNumber(firstKey(payload, ["serviceFeeVAT"]));
    const bankName = firstKey(payload, ["bankName"])

    const ok = (/success|completed|complete/i.test(String(statusText ?? ""))
        || String(firstKey(payload, ["ok", "valid"])).toLowerCase() === "true")
        && amount != null
        && totalAmount != null
        && currency != null
        && payerName != null
        && payerPhone != null
        && receiverName != null
        && receiverAccount != null
        && txnDate != null
        && serviceFee != null
        && serviceFeeVAT != null
        && bankName != null

    if (!ok) {
        var errorMessage: NormalizedVerificationFailed = {
            ok: false,
            provider: "telebirr",
            error: statusText ? String(statusText).toLowerCase() : "mismatch",
        };

        if (opts.mode == "both") {
            return {
                normalized: errorMessage,
                raw,
            };
        } else {
            return errorMessage;
        }
    }

    const normalized: NormalizedVerificationSuccess<NormalizedTelebirrDataVerification> = {
        ok: true,
        provider: "telebirr",
        data: {
            reference: args.reference,
            amount: amount ?? 0,
            currency,
            payerName,
            payerPhone,
            receiverName,
            receiverAccount,
            bankName,
            txnDate,
            serviceFee: serviceFee ?? 0,
            serviceFeeVAT: serviceFeeVAT ?? 0,
            totalAmount: totalAmount ?? 0,
            statusText,
            status: "verified",
        },
        raw,
    };

    if (opts.mode === "both") return { normalized, raw };
    return normalized;
}
