import { NormalizedCBEVerification, VerifyOptions, CBEArgs, BothResult, NormalizedVerificationSuccess, NormalizedCBEDataVerification, NormalizedVerificationFailed } from "../types";
import { firstKey, toNumber } from "../utils";
import { HttpClient } from "./base";

export async function verifyCBEAdapter(
    http: HttpClient,
    args: CBEArgs,
    opts: VerifyOptions = {},
): Promise<BothResult<NormalizedCBEVerification> | NormalizedCBEVerification> {
    const raw = await http.request("/verify-cbe", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ reference: args.reference, accountSuffix: args.accountSuffix }),
    });

    const payload: any = (raw && typeof raw === "object" && (raw as any).data) ? (raw as any).data : raw;

    if (opts.mode === "raw") return raw;


    const success = firstKey(payload, ["success"]);
    const payerName = firstKey(payload, ["payer"]);
    const payerAccount = firstKey(payload, ["payerAccount"]);
    const receiverName = firstKey(payload, ["receiver"]);
    const receiverAccount = firstKey(payload, ["receiverAccount"]);
    const amount = toNumber(firstKey(payload, ["amount"]));
    const txnDate = firstKey(payload, ["date"]);
    const reference = firstKey(payload, ["reference"]);
    const reason = firstKey(payload, ["reason"]);
    const currency = firstKey(payload, ["currency", "curr"]) ?? (amount != null ? "ETB" : null);

    const ok = success
        && amount != null
        && currency != null
        && payerName != null
        && payerAccount != null
        && receiverName != null
        && receiverAccount != null
        && txnDate != null
        && reference != null;

    if (!ok) {
        var errorMessage: NormalizedVerificationFailed = {
            ok: false,
            provider: "cbe",
            error: (raw as any).error ?? "mismatch",
        };

        if (opts.mode == "both") {
            return {
                normalized: errorMessage,
                raw,
            };
        } else {
            return errorMessage;
        }
    }

    const normalized: NormalizedVerificationSuccess<NormalizedCBEDataVerification> = {
        ok: true,
        provider: "cbe",
        data: {
            reference: args.reference,
            amount: amount ?? 0,
            currency,
            payerName: payerName,
            payerAccount: payerAccount,
            receiverName: receiverName,
            receiverAccount: receiverAccount,
            txnDate: txnDate,
            reason: reason,
        },
        raw,
    };

    if (opts.mode === "both") return { normalized, raw };
    return normalized;
}
