import {
  VerifyOptions,
  ReferenceArg,
  CBEArgs,
  AbyssiniaArgs,
  BothResult,
  NormalizedTelebirrVerification,
  NormalizedCBEVerification,
  NormalizedAbyssiniaVerification,
  NormalizedDashenVerification,
  NormalizedCBEBirrVerification,
  NormalizedMpesaVerification,
  NormalizedUniversalVerification,
  MpesaArgs,
  UniversalArgs,
} from "./types";

import { verifyTelebirrAdapter } from "./adapters/telebirr";
import { verifyCBEAdapter } from "./adapters/cbe";
import { verifyCBEBirrAdapter } from "./adapters/cbebirr";
import { verifyDashenAdapter } from "./adapters/dashen";
import { verifyAbyssiniaAdapter } from "./adapters/abyssinia";
import { verifyMpesaAdapter } from "./adapters/mpesa";
import { verifyUniversalAdapter } from "./adapters/universal";
import { HttpClient } from "./adapters/base";
import { VerifierError } from "./errors";

export type VerifierClientConfig = ConstructorParameters<typeof HttpClient>[0];

export class VerifierClient {
  private http: HttpClient;

  constructor(cfg: VerifierClientConfig) {
    this.http = new HttpClient(cfg);
  }

  get baseUrl() {
    return this.http["url"];
  }

  /**
   * Telebirr by reference
   */
  verifyTelebirr(args: ReferenceArg, opts: { mode: "raw" }): Promise<unknown>;
  verifyTelebirr(
    args: ReferenceArg,
    opts: { mode: "both" },
  ): Promise<BothResult<NormalizedTelebirrVerification>>;
  verifyTelebirr(args: ReferenceArg, opts?: VerifyOptions): Promise<NormalizedTelebirrVerification>;
  verifyTelebirr(
    args: ReferenceArg,
    opts?: VerifyOptions,
  ): Promise<BothResult<NormalizedTelebirrVerification> | NormalizedTelebirrVerification> {
    return verifyTelebirrAdapter(this.http, args, opts ?? {});
  }

  /**
   * CBE by reference + account suffix
   */
  verifyCBE(args: CBEArgs, opts: { mode: "raw" }): Promise<unknown>;
  verifyCBE(args: CBEArgs, opts: { mode: "both" }): Promise<BothResult<NormalizedCBEVerification>>;
  verifyCBE(args: CBEArgs, opts?: VerifyOptions): Promise<NormalizedCBEVerification>;
  verifyCBE(
    args: CBEArgs,
    opts?: VerifyOptions,
  ): Promise<BothResult<NormalizedCBEVerification> | NormalizedCBEVerification> {
    return verifyCBEAdapter(this.http, args, opts ?? {});
  }

  /**
   * CBE Birr (wallet) by reference
   */
  verifyCBEBirr(args: ReferenceArg, opts: { mode: "raw" }): Promise<unknown>;
  verifyCBEBirr(
    args: ReferenceArg,
    opts: { mode: "both" },
  ): Promise<BothResult<NormalizedCBEBirrVerification>>;
  verifyCBEBirr(args: ReferenceArg, opts?: VerifyOptions): Promise<NormalizedCBEBirrVerification>;
  verifyCBEBirr(
    args: ReferenceArg,
    opts?: VerifyOptions,
  ): Promise<BothResult<NormalizedCBEBirrVerification> | NormalizedCBEBirrVerification> {
    return verifyCBEBirrAdapter(this.http, args, opts ?? {});
  }

  /**
   * Dashen by reference
   */
  verifyDashen(args: ReferenceArg, opts: { mode: "raw" }): Promise<unknown>;
  verifyDashen(
    args: ReferenceArg,
    opts: { mode: "both" },
  ): Promise<BothResult<NormalizedDashenVerification>>;
  verifyDashen(args: ReferenceArg, opts?: VerifyOptions): Promise<NormalizedDashenVerification>;
  verifyDashen(
    args: ReferenceArg,
    opts?: VerifyOptions,
  ): Promise<BothResult<NormalizedDashenVerification> | NormalizedDashenVerification> {
    return verifyDashenAdapter(this.http, args, opts ?? {});
  }

  /**
   * Bank of Abyssinia by reference
   * (keep signature as-is until we add suffix to args)
   */
  verifyAbyssinia(args: AbyssiniaArgs, opts: { mode: "raw" }): Promise<unknown>;
  verifyAbyssinia(
    args: AbyssiniaArgs,
    opts: { mode: "both" },
  ): Promise<BothResult<NormalizedAbyssiniaVerification>>;
  verifyAbyssinia(
    args: AbyssiniaArgs,
    opts?: VerifyOptions,
  ): Promise<NormalizedAbyssiniaVerification>;
  verifyAbyssinia(
    args: AbyssiniaArgs,
    opts?: VerifyOptions,
  ): Promise<BothResult<NormalizedAbyssiniaVerification> | NormalizedAbyssiniaVerification> {
    return verifyAbyssiniaAdapter(this.http, args, opts ?? {});
  }

  /**
   * M-Pesa by receipt number and phone number
   */
  verifyMpesa(args: MpesaArgs, opts: { mode: "raw" }): Promise<unknown>;
  verifyMpesa(
    args: MpesaArgs,
    opts: { mode: "both" },
  ): Promise<BothResult<NormalizedMpesaVerification>>;
  verifyMpesa(args: MpesaArgs, opts?: VerifyOptions): Promise<NormalizedMpesaVerification>;
  verifyMpesa(
    args: MpesaArgs,
    opts?: VerifyOptions,
  ): Promise<BothResult<NormalizedMpesaVerification> | NormalizedMpesaVerification> {
    return verifyMpesaAdapter(this.http, args, opts ?? {});
  }

  /**
   * Universal Smart Router
   */
  verifyUniversal(args: UniversalArgs, opts: { mode: "raw" }): Promise<unknown>;
  verifyUniversal(
    args: UniversalArgs,
    opts: { mode: "both" },
  ): Promise<BothResult<NormalizedUniversalVerification>>;
  verifyUniversal(
    args: UniversalArgs,
    opts?: VerifyOptions,
  ): Promise<NormalizedUniversalVerification>;
  verifyUniversal(
    args: UniversalArgs,
    opts?: VerifyOptions,
  ): Promise<BothResult<NormalizedUniversalVerification> | NormalizedUniversalVerification> {
    return verifyUniversalAdapter(this.http, args, opts ?? {});
  }
}

// Convenience default export
export default VerifierClient;
export { VerifierError };
