import {
  BothResult,
  NormalizedMpesaDataVerification,
  NormalizedMpesaVerification,
  NormalizedVerificationFailed,
  NormalizedVerificationSuccess,
  VerifyOptions,
  MpesaArgs,
} from "../types";
import { firstKey, toNumber } from "../utils";
import { HttpClient } from "./base";

export async function verifyMpesaAdapter(
  http: HttpClient,
  args: MpesaArgs,
  opts: VerifyOptions = {},
): Promise<BothResult<NormalizedMpesaVerification> | NormalizedMpesaVerification> {
  const raw = await http.request("/verify-mpesa", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ reference: args.receiptNumber }),
  });

  const payload: any =
    raw && typeof raw === "object" && (raw as any).data ? (raw as any).data : raw;

  if (opts.mode === "raw") return raw;

  const success = firstKey(payload, ["success", "ok", "valid"]);
  const payerName = firstKey(payload, ["payerName"]);
  const payerAccount = firstKey(payload, ["payerAccount"]);
  const receiverName = firstKey(payload, ["receiverName"]);
  const receiverAccount = firstKey(payload, ["receiverAccount"]);
  const transactionId = firstKey(payload, ["transactionId"]);
  const receiptNo = firstKey(payload, ["receiptNo"]);
  const amount = toNumber(firstKey(payload, ["amount"]));
  const txnDate = firstKey(payload, ["paymentDate"]);
  const serviceFee = toNumber(firstKey(payload, ["serviceFee"]));
  const vat = toNumber(firstKey(payload, ["vat"]));
  // The API might not return currency, default to ETB
  const currency = firstKey(payload, ["currency"]) ?? (amount != null ? "ETB" : null);

  const isSuccess = String(success).toLowerCase() === "true" || success === true;

  const ok =
    isSuccess &&
    amount != null &&
    currency != null &&
    payerName != null &&
    payerAccount != null &&
    receiverName != null &&
    receiverAccount != null &&
    txnDate != null &&
    transactionId != null &&
    receiptNo != null;

  if (!ok) {
    var errorMessage: NormalizedVerificationFailed = {
      ok: false,
      provider: "mpesa",
      error: (raw as any).error ?? "mismatch",
    };

    if (opts.mode == "both") {
      return {
        normalized: errorMessage,
        raw,
      };
    } else {
      return errorMessage;
    }
  }

  const normalized: NormalizedVerificationSuccess<NormalizedMpesaDataVerification> = {
    ok: true,
    provider: "mpesa",
    data: {
      reference: receiptNo,
      amount: amount ?? 0,
      currency,
      payerName,
      payerAccount,
      receiverName,
      receiverAccount,
      txnDate,
      serviceFee: serviceFee ?? 0,
      vat: vat ?? 0,
      transactionId,
    },
    raw,
  };

  if (opts.mode === "both") return { normalized, raw };
  return normalized;
}
