export function toNumber(v: any): number | null {
    if (v == null) return null;
    const s = String(v).replace(/[^\d.-]/g, "");
    if (!s) return null;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
}

export function firstKey(raw: any, keys: string[]): any {
    if (!raw || typeof raw !== "object") return null;
    const lower = new Map<string, any>();
    for (const [k, v] of Object.entries(raw)) lower.set(k.toLowerCase(), v);
    for (const k of keys) {
        const v = lower.get(k.toLowerCase());
        if (v !== undefined) return v;
    }
    return null;
}

export function buildQuery(url: string, params: Record<string, any> = {}) {
    const u = new URL(url);
    for (const [k, v] of Object.entries(params)) {
        if (v === undefined || v === null) continue;
        u.searchParams.set(k, String(v));
    }
    return u.toString();
}
