export type VerifierErrorMeta = {
    status?: number;
    data?: unknown;
};

export class VerifierError extends Error {
    status?: number;
    data?: unknown;

    constructor(message: string, meta?: VerifierErrorMeta) {
        super(message);
        this.name = 'VerifierError';
        this.status = meta?.status;
        this.data = meta?.data;
    }
}

export class RateLimitError extends VerifierError {
    constructor(message = "Rate limit exceeded", meta?: VerifierErrorMeta) {
        super(message, meta);
        this.name = 'RateLimitError';
    }
}
