import { VerifierError, RateLimitError } from "../errors";

export type ClientConfig = {
    baseUrl?: string;        // optional; defaults to official API base
    timeoutMs?: number;      // optional
    userAgent?: string;      // optional
    headers?: Record<string, string>; // optional extra headers
    apiKey?: string;         // optional; will be sent in x-api-key header
    max429Retries?: number;  // optional; default 1 retry after initial 429
    retryDelayMs?: number;   // optional; base delay for 429 backoff (default 300ms)
};

export class HttpClient {
    private baseUrl: string;
    private timeoutMs?: number;
    private userAgent?: string;
    private headers?: Record<string, string>;
    private apiKey?: string;
    private max429Retries: number;
    private retryDelayMs: number;

    constructor(cfg: ClientConfig) {
        // Default base URL if none is provided
        this.baseUrl = (cfg.baseUrl ?? "https://verifyapi.leulzenebe.pro").replace(/\/+$/, "");
        this.timeoutMs = cfg.timeoutMs;
        this.userAgent = cfg.userAgent;
        this.headers = cfg.headers;
        this.apiKey = cfg.apiKey;
        this.max429Retries = cfg.max429Retries ?? 1;
        this.retryDelayMs = cfg.retryDelayMs ?? 300;
    }

    get url() {
        return this.baseUrl;
    }

    async request(path: string, options: RequestInit & { query?: Record<string, any> } = {}) {
        const urlObj = new URL(this.baseUrl + (path.startsWith("/") ? path : `/${path}`));
        if (options.query) {
            for (const [k, v] of Object.entries(options.query)) {
                if (v !== undefined && v !== null) urlObj.searchParams.set(k, String(v));
            }
        }

        const controller = this.timeoutMs ? new AbortController() : undefined;
        const id = this.timeoutMs ? setTimeout(() => controller!.abort(), this.timeoutMs) : undefined;

        try {
            let attempt = 0;

            while (true) {
                const res = await fetch(urlObj.toString(), {
                    method: options.method ?? "GET",
                    headers: {
                        "accept": "application/json",
                        ...(this.userAgent ? { "user-agent": this.userAgent } : {}),
                        ...(this.apiKey ? { "x-api-key": this.apiKey } : {}),
                        ...(this.headers ?? {}),
                        ...(options.headers ?? {}),
                    },
                    body: options.body,
                    signal: controller?.signal,
                });

                const contentType = res.headers.get("content-type") || "";
                const isJson = contentType.includes("application/json");
                const data = isJson ? await res.json().catch(() => null) : await res.text();

                if (res.status === 429) {
                    if (attempt < this.max429Retries) {
                        const delay = this.retryDelayMs * Math.pow(2, attempt);
                        await new Promise(r => setTimeout(r, delay));
                        attempt += 1;
                        continue;
                    }
                    const snippet = typeof data === "string" ? data.slice(0, 500) : JSON.stringify(data);
                    throw new RateLimitError(snippet || `HTTP 429`, { status: res.status, data });
                }

                if (!res.ok) {
                    // Bubble up server error (e.g., 404 from wrong base / path)
                    const snippet = typeof data === "string" ? data.slice(0, 500) : JSON.stringify(data);
                    throw new VerifierError(snippet || `HTTP ${res.status}`, { status: res.status, data });
                }

                return data;
            }
        } finally {
            if (id) clearTimeout(id);
        }
    }
}
