import { VerifyOptions, AbyssiniaArgs, BothResult, NormalizedAbyssiniaVerification, NormalizedVerificationSuccess, NormalizedAbyssiniaDataVerification, NormalizedVerificationFailed } from "../types";
import { firstKey, toNumber } from "../utils";
import { HttpClient } from "./base";

export async function verifyAbyssiniaAdapter(
    http: HttpClient,
    args: AbyssiniaArgs,
    opts: VerifyOptions = {},
): Promise<BothResult<NormalizedAbyssiniaVerification> | NormalizedAbyssiniaVerification> {
    const raw = await http.request("/verify-abyssinia", {
        method: "GET",
        query: { reference: args.reference, suffix: args.suffix },
    });

    const payload: any = (raw && typeof raw === "object" && (raw as any).data) ? (raw as any).data : raw;

    if (opts.mode === "raw") return raw;

    const amount = toNumber(firstKey(payload, ["amount"]));
    const success = firstKey(payload, ["success"]);
    const currency = firstKey(payload, ["currency"]) ?? (amount != null ? "ETB" : null);
    const payerName = firstKey(payload, ["payer"]);
    const payerAccount = firstKey(payload, ["payerAccount"]);
    const receiverName = firstKey(payload, ["receiver"]);
    const txnDate = firstKey(payload, ["date"]);
    const reason = firstKey(payload, ["reason"]);

    const ok = success
        && amount != null
        && currency != null
        && payerName != null
        && payerAccount != null
        && receiverName != null
        && reason != null
        && txnDate != null;

    if (!ok) {
        var errorMessage: NormalizedVerificationFailed = {
            ok: false,
            provider: "abyssinia",
            error: (raw as any).error ?? "mismatch",
        };

        if (opts.mode == "both") {
            return {
                normalized: errorMessage,
                raw,
            };
        } else {
            return errorMessage;
        }
    }

    const normalized: NormalizedVerificationSuccess<NormalizedAbyssiniaDataVerification> = {
        ok: true,
        provider: "abyssinia",
        data: {
            reference: args.reference,
            amount: amount ?? 0,
            currency,
            payerName,
            payerAccount,
            receiverName,
            txnDate,
            reason: reason
        },
        raw,
    };

    if (opts.mode === "both") return { normalized, raw };
    return normalized;
}
